using System;using System.Diagnostics;using System.IO;using System.Runtime.InteropServices;using System.Security.Principal;using System.Threading.Tasks;using Microsoft.Win32.SafeHandles;using Newtonsoft.Json.Linq;
namespace JonsboStudio {
 static class SensorSetup {
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern SafeFileHandle CreateFile(string name,uint access,uint share,IntPtr security,uint disposition,uint flags,IntPtr template);
  public static bool IsAdministrator{get{using(var identity=WindowsIdentity.GetCurrent())return new WindowsPrincipal(identity).IsInRole(WindowsBuiltInRole.Administrator);}}
  static DateTime checkedDriver=DateTime.MinValue;static bool driverAccessible;public static bool DriverAccessible{get{if((DateTime.UtcNow-checkedDriver).TotalSeconds<5)return driverAccessible;checkedDriver=DateTime.UtcNow;using(var handle=CreateFile(@"\\?\GLOBALROOT\Device\PawnIO",0xC0000000,3,IntPtr.Zero,3,0,IntPtr.Zero))return driverAccessible=!handle.IsInvalid;}}
  public static string PreferencePath{get{return Path.Combine(AppPaths.Data("Settings"),"hardware-sensors.json");}}
  public static bool PreferAdministrator{get{try{return (bool?)JObject.Parse(File.ReadAllText(PreferencePath))["administrator"]==true;}catch{return false;}}}
  public static string Status(SensorSnapshot sample){if(sample.Get("CPUTemp","").Length>0)return "CPU temperature is live. RAM and network counters update without the hardware driver.";if(!IsAdministrator)return "CPU temperature requires hardware access. Enable hardware sensors to install the signed PawnIO driver and restart Studio as administrator.";if(!DriverAccessible)return "PawnIO is missing or unavailable. Enable hardware sensors to install or repair the signed driver. A Windows restart may be needed after installation.";return "Hardware access is ready, but this processor or virtual machine is not exposing CPU temperature. Unsupported sensors show a dash.";}
  public static void RememberAdministrator(){AppPaths.SaveJson(PreferencePath,new JObject{{"administrator",true}});}
  public static void StartReplacement(bool setup,bool background=false){var info=new ProcessStartInfo(System.Windows.Forms.Application.ExecutablePath,"--wait-for-exit "+Process.GetCurrentProcess().Id+(setup?" --setup-sensors":"")+(background?" --background":"")){UseShellExecute=true,WorkingDirectory=AppPaths.Root};if(setup||PreferAdministrator)info.Verb="runas";Process.Start(info);}
  public static int Install(){if(!IsAdministrator)throw new InvalidOperationException("Hardware sensor setup requires Windows administrator approval.");string script=Path.Combine(AppPaths.Root,"Assets","Setup","Sensors.ps1");if(!File.Exists(script))throw new FileNotFoundException("Sensor setup is missing. Extract the complete Studio ZIP.");var info=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe"),"-NoProfile -ExecutionPolicy Bypass -File \""+script+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true};using(var process=Process.Start(info)){var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(180000)){try{process.Kill();}catch{}throw new IOException("Hardware sensor setup timed out.");}Task.WaitAll(stdout,stderr);if(process.ExitCode!=0&&process.ExitCode!=3010)throw new IOException("Hardware sensor setup did not complete: "+stderr.Result.Trim());return process.ExitCode;}}
 }
}
